using System.ComponentModel;
using System.Text.Json;
using ModelContextProtocol.Server;

[McpServerResourceType]
public static class ConfigResources
{
    [McpServerResource(UriTemplate = "config://app/settings", Name = "App Settings",
        MimeType = "application/json")]
    [Description("Returns the current application configuration")]
    public static string GetAppSettings()
    {
        var config = new
        {
            AppName = "ConfigMcpServer",
            Version = "1.0.0",
            Environment = Environment.GetEnvironmentVariable("ASPNETCORE_ENVIRONMENT") ?? "Production",
            MaxRetries = 3,
            TimeoutSeconds = 30
        };

        return JsonSerializer.Serialize(config, new JsonSerializerOptions { WriteIndented = true });
    }

    [McpServerResource(UriTemplate = "config://app/features", Name = "Feature Flags",
        MimeType = "application/json")]
    [Description("Returns current feature flag settings")]
    public static string GetFeatureFlags()
    {
        var flags = new
        {
            EnableCaching = true,
            EnableDetailedLogging = false,
            MaxConcurrentRequests = 100
        };

        return JsonSerializer.Serialize(flags, new JsonSerializerOptions { WriteIndented = true });
    }
}

using System.ComponentModel;
using ModelContextProtocol.Server;

[McpServerToolType]
public static class ConfigTools
{
    [McpServerTool, Description("Gets the value of an environment variable")]
    public static string GetEnvVariable(
        [Description("Name of the environment variable to read")] string name)
    {
        var value = Environment.GetEnvironmentVariable(name);
        return value is not null
            ? $"{name}={value}"
            : $"Environment variable '{name}' is not set.";
    }

    [McpServerTool, Description("Returns server uptime and runtime information")]
    public static string GetServerInfo()
    {
        return $"""
            Runtime: {System.Runtime.InteropServices.RuntimeInformation.FrameworkDescription}
            OS: {System.Runtime.InteropServices.RuntimeInformation.OSDescription}
            Process uptime: {DateTime.UtcNow - System.Diagnostics.Process.GetCurrentProcess().StartTime.ToUniversalTime():hh\:mm\:ss}
            """;
    }
}

